// Planifie jusqu'à 21 contenus (3 slots × 7 jours) avec répartition équilibrée par réseau.
// Slots 9h / 13h / 18h UTC (= Dakar GMT+0). Préfère 1 post/réseau/jour mais accepte surplus si nécessaire.

const all = $input.all().map(i => i.json);
// Tri par createdTime asc
all.sort((a, b) => (a.createdTime || '').localeCompare(b.createdTime || ''));

const SLOTS = [9, 13, 18];
const DAYS = 7;

// Helper pour extraire le réseau (fallback sur ancien schema)
function getReseau(item) {
  if (item.Reseau) return String(item.Reseau).toLowerCase();
  if (item.Plateforme_Principale) {
    const m = { facebook:'fb', instagram:'ig', tiktok:'tiktok', youtube:'youtube', linkedin:'linkedin', twitter:'x' };
    return m[String(item.Plateforme_Principale).toLowerCase()] || 'linkedin';
  }
  if (Array.isArray(item.Reseaux_Cibles) && item.Reseaux_Cibles.length) {
    return String(item.Reseaux_Cibles[0]).toLowerCase();
  }
  return 'linkedin';
}

// On prend tous les items (la limite vient du nombre de slots dispo)
const queue = all.slice();

// Construire la grille 7j × 3 slots
const grid = [];
for (let d = 1; d <= DAYS; d++) {
  for (const h of SLOTS) {
    grid.push({ day: d, hour: h, reseaux: [] });
  }
}
const MAX = grid.length; // 21

const now = new Date();
const results = [];
const usedSlots = new Set();

for (const item of queue) {
  if (results.length >= MAX) break;
  const r = getReseau(item);

  // Pass 1 : trouver un slot libre où ce réseau n'a PAS encore posté ce jour-là
  let chosen = -1;
  for (let i = 0; i < grid.length; i++) {
    if (usedSlots.has(i)) continue;
    // Vérifier si un autre slot du même jour a déjà ce réseau
    const sameDayHasReseau = grid.some((g, gi) => g.day === grid[i].day && g.reseaux.includes(r));
    if (!sameDayHasReseau) { chosen = i; break; }
  }
  // Pass 2 : n'importe quel slot libre (fallback si saturation mono-réseau)
  if (chosen === -1) {
    for (let i = 0; i < grid.length; i++) {
      if (!usedSlots.has(i)) { chosen = i; break; }
    }
  }
  if (chosen === -1) break; // grille pleine

  usedSlots.add(chosen);
  grid[chosen].reseaux.push(r);

  const d = new Date(now);
  d.setUTCDate(now.getUTCDate() + grid[chosen].day);
  d.setUTCHours(grid[chosen].hour, 0, 0, 0);

  results.push({ json: {
    id: item.id,
    Status: 'planifié',
    Date_Publication_Prevue: d.toISOString()
  }});
}

return results;

